(2637822, 364270, 40355, '<td valign="top">Great capture, very nicely done.</td>', 'Great capture, very nicely done.', '2006-07-19 13:28:43.000000', NULL, 1),
(2637823, 366086, 61818, '<td valign="top">Very nice. 7.</td>', 'Very nice. 7.', '2006-07-19 13:28:43.000000', NULL, 1),
(2637828, 365674, 40355, '<td valign="top">The movement from shadow to light here is very nice, and the exposure for both is right on - no over or under exposure.  Overall, just a heck of an image.  Might be cool to see it in B&amp;W, too.  10</td>', 'The movement from shadow to light here is very nice, and the exposure for both is right on - no over or under exposure.  Overall, just a heck of an image.  Might be cool to see it in B&W, too.  10', '2006-07-19 13:30:26.000000', NULL, 1),
(2637829, 365775, 61818, '<td valign="top">Did you find the hottest gal on the beach and then purposely throw as much junk in front of her as possible?</td>', 'Did you find the hottest gal on the beach and then purposely throw as much junk in front of her as possible?', '2006-07-19 13:30:30.000000', NULL, 1),
(2637830, 365301, 57202, '<td valign="top">Awesome colors, great composition, and I like that you managed to capture that seagull in the shot as well. :)</td>', 'Awesome colors, great composition, and I like that you managed to capture that seagull in the shot as well. :)', '2006-07-19 13:30:31.000000', NULL, 1),
