(2641479, 364081, 47294, '<td valign="top">God DAMN!!!!!<br/> <br/>Fantastic photo, congrats on your ribbon ;)</td>', 'God DAMN!!!!! Fantastic photo, congrats on your ribbon ;)', '2006-07-20 06:18:24.000000', NULL, 1),
(2641485, 366095, 62490, '<td valign="top">Nice Compositon and coloring</td>', 'Nice Compositon and coloring', '2006-07-20 06:22:11.000000', NULL, 1),
