(2642925, 364633, 59748, '<td valign="top">Nicely done</td>', 'Nicely done', '2006-07-20 15:52:27.000000', NULL, 1),
(2642929, 365513, 42100, '<td valign="top">Fun use of long exposure on this, the misty water is very cool.  Great job!</td>', 'Fun use of long exposure on this, the misty water is very cool.  Great job!', '2006-07-20 15:52:54.000000', NULL, 1),
(2642930, 364270, 42100, '<td valign="top">Amazing crisp and colorful detail.  Awesome photo!</td>', 'Amazing crisp and colorful detail.  Awesome photo!', '2006-07-20 15:53:34.000000', NULL, 1),
