(2644122, 365303, 12733, '<td valign="top">An interesting idea, and nice texture capture. Not a terribly interesting subject, though.</td>', 'An interesting idea, and nice texture capture. Not a terribly interesting subject, though.', '2006-07-20 21:09:03.000000', NULL, 1),
(2644124, 365252, 12733, '<td valign="top">Nice colors and textures.</td>', 'Nice colors and textures.', '2006-07-20 21:09:32.000000', NULL, 1),
