(2650708, 365498, 9668, '<td valign="top">Nice alpenglow on Mt. Ranier!</td>', 'Nice alpenglow on Mt. Ranier!', '2006-07-23 06:35:25.000000', NULL, 1),
(2650709, 365766, 9668, '<td valign="top">Awesome capture. The perspective and lighting really make the photo.</td>', 'Awesome capture. The perspective and lighting really make the photo.', '2006-07-23 06:36:13.000000', NULL, 1),
(2650710, 363900, 9668, '<td valign="top">Love the human element combined with the natural element.</td>', 'Love the human element combined with the natural element.', '2006-07-23 06:36:43.000000', NULL, 1),
(2650711, 366059, 9668, '<td valign="top">Lovely lighting! Fun concept too!</td>', 'Lovely lighting! Fun concept too!', '2006-07-23 06:37:12.000000', NULL, 1),
(2650712, 365968, 9668, '<td valign="top">Awesome capture, and though it does have a beach, it doesn''t say "beach" to me.  Think the title could be a bit better too...</td>', 'Awesome capture, and though it does have a beach, it doesn''t say "beach" to me.  Think the title could be a bit better too...', '2006-07-23 06:38:37.000000', NULL, 1),
(2650713, 363260, 9668, '<td valign="top">Cannon Beach! I live here! Who is this? When were you down here? Why didn''t you let me know, I could have gone shooting with you? Cool image, the low mist is very cool.</td>', 'Cannon Beach! I live here! Who is this? When were you down here? Why didn''t you let me know, I could have gone shooting with you? Cool image, the low mist is very cool.', '2006-07-23 06:39:58.000000', NULL, 1),
(2650715, 364725, 9668, '<td valign="top">Peter Iredale! Lovely silhouette capture!</td>', 'Peter Iredale! Lovely silhouette capture!', '2006-07-23 06:41:17.000000', NULL, 1),
(2650717, 364994, 9668, '<td valign="top">Best Golden Gate Bridge I''ve seen in this challenge. Beautiful capture!</td>', 'Best Golden Gate Bridge I''ve seen in this challenge. Beautiful capture!', '2006-07-23 06:42:31.000000', NULL, 1),
(2650720, 365889, 49969, '<td valign="top">i wish you had taken a slightly higher vintage point so that the wrecked boat wouldn''t intrude this much over the horizon. But it''s a very pretty shot nonetheless.</td>', 'i wish you had taken a slightly higher vintage point so that the wrecked boat wouldn''t intrude this much over the horizon. But it''s a very pretty shot nonetheless.', '2006-07-23 06:50:36.000000', NULL, 1),
(2650727, 364399, 49969, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2006-07-23 06:57:07.000000', NULL, 1),
