(2651070, 365335, 50357, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-07-23 11:50:29.000000', NULL, 1),
(2651071, 365339, 50357, '<td valign="top">Beautiful beach, great shot!</td>', 'Beautiful beach, great shot!', '2006-07-23 11:50:59.000000', NULL, 1),
(2651072, 365361, 48890, '<td valign="top">This would be a great reportage shot in B&amp;W.  Here the colours are too many, and are distracting from the composition.</td>', 'This would be a great reportage shot in B&W.  Here the colours are too many, and are distracting from the composition.', '2006-07-23 11:51:19.000000', NULL, 1),
(2651074, 366107, 50357, '<td valign="top">Wow!</td>', 'Wow!', '2006-07-23 11:51:47.000000', NULL, 1),
(2651077, 365567, 50357, '<td valign="top">What a beautiful picture--I''m sure they will treasure this.</td>', 'What a beautiful picture--I''m sure they will treasure this.', '2006-07-23 11:52:56.000000', NULL, 1),
(2651081, 366209, 50357, '<td valign="top">Very very cute!  Great shot!!  Good Luck to you!</td>', 'Very very cute!  Great shot!!  Good Luck to you!', '2006-07-23 11:54:19.000000', NULL, 1),
