(2651124, 365821, 26633, '<td valign="top">"Rubble-rummaging" Aftermath style... Very interesting.</td>', '"Rubble-rummaging" Aftermath style... Very interesting.', '2006-07-23 12:29:07.000000', NULL, 1),
(2651221, 363533, 26633, '<td valign="top">Nice simple picture with good colours and great light. I like the reflections of the rippling water on the hulls of the yachts. Looks like a slight tilt though...</td>', 'Nice simple picture with good colours and great light. I like the reflections of the rippling water on the hulls of the yachts. Looks like a slight tilt though...', '2006-07-23 13:38:09.000000', NULL, 1),
(2651381, 365609, 57636, '<td valign="top">I think it looks neat.  I will give it an 8.</td>', 'I think it looks neat.  I will give it an 8.', '2006-07-23 15:30:28.000000', NULL, 1),
