INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2651629, 364219, 35530, '<td valign="top">Nice composition. There is a little vignetting. Was it on purpose?</td>', 'Nice composition. There is a little vignetting. Was it on purpose?', '2006-07-23 17:27:23.000000', NULL, 1),
(2651683, 365883, 62249, '<td valign="top">Very dreamy.</td>', 'Very dreamy.', '2006-07-23 18:10:34.000000', NULL, 1),
(2651692, 365630, 62249, '<td valign="top">Great title.</td>', 'Great title.', '2006-07-23 18:15:29.000000', NULL, 1),
(2651707, 365230, 62249, '<td valign="top">Try cropping out the left side of the photo (the whole building on the left) so that the water tower is more on the left and the Blue Angels more centered.</td>', 'Try cropping out the left side of the photo (the whole building on the left) so that the water tower is more on the left and the Blue Angels more centered.', '2006-07-23 18:25:07.000000', NULL, 1),
