(2656813, 364824, 12733, '<td valign="top">Nice idea, nice colors.</td>', 'Nice idea, nice colors.', '2006-07-24 23:34:17.000000', NULL, 1),
(2656815, 365788, 12733, '<td valign="top">This is way too small. While there are good reasons for making a vertical shot smaller than the maximum allowed, it should fill the screen. This is just too hard to see.</td>', 'This is way too small. While there are good reasons for making a vertical shot smaller than the maximum allowed, it should fill the screen. This is just too hard to see.', '2006-07-24 23:35:36.000000', NULL, 1),
