(2656835, 365633, 12733, '<td valign="top">Interesting combination of foreground shapes and colors with background textures and shapes.</td>', 'Interesting combination of foreground shapes and colors with background textures and shapes.', '2006-07-24 23:42:04.000000', NULL, 1),
(2656838, 366020, 12733, '<td valign="top">The large amount of out-of-focus brilliance is difficult to look at. The shapes are interesting, but seem meaningless in the context of the brilliant sunset.</td>', 'The large amount of out-of-focus brilliance is difficult to look at. The shapes are interesting, but seem meaningless in the context of the brilliant sunset.', '2006-07-24 23:43:37.000000', NULL, 1),
